function kthBadge(tree, k) {
  const values = tree.filter((v) => v !== null).sort((a, b) => a - b);
  return values[k - 1];
}

function kthBadge(tree, k) {
  const root = { value: tree[0], left: null, right: null };
  const queue = [root];
  for (let i = 1, head = 0; i < tree.length; head++) {
    const node = queue[head];
    if (tree[i] !== null && tree[i] !== undefined) queue.push(node.left = { value: tree[i], left: null, right: null });
    i++;
    if (i < tree.length && tree[i] !== null) queue.push(node.right = { value: tree[i], left: null, right: null });
    i++;
  }
  const stack = [];
  let node = root;
  while (node || stack.length) {
    while (node) { stack.push(node); node = node.left; }
    node = stack.pop();
    if (--k === 0) return node.value;
    node = node.right;
  }
  return -1;
}
